const fs = require('fs');
const path = require('path');

const ICONSCOUT_DIRS = [
  path.join(__dirname, '../assets/iconscout'),
  path.join(__dirname, '../assets/iconscout/sport-215'),
  path.join(__dirname, '../assets/iconscout/stay-at-home-14'),
  path.join(__dirname, '../assets/iconscout/mental-health-143'),
];
const REGISTRY_PATH = path.join(__dirname, '../src/components/icons/iconScoutRegistry.ts');

function generateRegistry() {
  console.log('Generating IconScout registry...');

  let registryContent = `/**
 * AUTO-GENERATED FILE - DO NOT EDIT DIRECTLY
 * Generated by scripts/generate-iconscout-registry.js
 * Contains all IconScout SVG assets as string constants.
 */

export const ICONSCOUT_ICONS: Record<string, string> = {
`;

  let processedCount = 0;

  ICONSCOUT_DIRS.forEach(dir => {
    if (fs.existsSync(dir)) {
      const files = fs.readdirSync(dir).filter(file => file.endsWith('.svg'));

      files.forEach(file => {
        const filePath = path.join(dir, file);
        const content = fs.readFileSync(filePath, 'utf-8');

        // Normalize name: remove .svg, convert to lowercase, replace spaces with hyphens
        let name = file.replace('.svg', '').toLowerCase().trim().replace(/\s+/g, '-');

        // Clean up SVG content:
        // - remove XML declaration
        // - remove doctype
        // - remove newlines and extra spaces
        let cleanContent = content
          .replace(/<\?xml.*?\?>/g, '')
          .replace(/<!DOCTYPE.*?>/g, '')
          .replace(/\r?\n|\r/g, '')
          .replace(/>\s+</g, '><')
          .trim();

        // Escape single quotes for TypeScript string literal
        cleanContent = cleanContent.replace(/'/g, "\\'");

        registryContent += `  '${name}': '${cleanContent}',\n`;
        processedCount++;
      });
    }
  });

  registryContent += `};

export type IconScoutName = keyof typeof ICONSCOUT_ICONS;
`;

  fs.writeFileSync(REGISTRY_PATH, registryContent);
  console.log(`Successfully generated registry with ${processedCount} icons at ${REGISTRY_PATH}`);
}

generateRegistry();
